function finalHtml(f){
 const headers=[{insertAdjacentHTML(){}}],row={html:'',insertAdjacentHTML(where,text){this.html+=text}};
 const thead={firstChild:headers[0],insertBefore(x){headers.unshift(x)},querySelectorAll:()=>headers};
 const table={querySelector:()=>thead,querySelectorAll:()=>[row]};f.api.finals({querySelector:()=>table,querySelectorAll:()=>[]});return row.html;
}
