function uploadUi(f){
 const order=[],messages=[];let academic={grades:{synthetic:{nota20:15}},finales:{},asistencia:{}};
 Object.assign(f.c,{guardarTodo:()=>{order.push('local');return true},sliceRegistroArea:()=>clone(academic),cloudClaveReg:()=> 'synthetic-key',CLOUD_API_URL:'synthetic',retirarVerificacionNube:()=>{},toast:m=>messages.push(m),fetch:async(url,p)=>{const body=JSON.parse(p.body);order.push(body.action);f.upload=body;return {status:200,text:async()=>JSON.stringify({ok:true})}}});
 const original=f.c.IETransversales.request;f.c.IETransversales.request=async(a,p)=>{order.push(a);return original(a,p)};
 vm.runInContext(extract('subirRegistroNube'),f.c);return {order,messages,setAcademic:p=>academic=p};
}
