test('Letter original has empty numeric direct field and stays a letter through view/capture/save',async()=>{const f=ui();direct(f.s,'A');await f.api.load();const e=f.api.current(),version=e.version;f.c.modoCalif='num';assert.match(finalHtml(f),/trans-direct-num[^>]*value=""/);assert.doesNotMatch(finalHtml(f),/value="15"/);const root=f.el('letter-summary');f.api.summary(root);assert.match(root.children[0].innerHTML,/>A<small>Directo/);assert.doesNotMatch(root.children[0].innerHTML,/15 →/);f.c.document.querySelectorAll=()=>[{value:'',dataset:{transEntry:String(e.id),transId:f.s.id,transComp:'tic'}}];f.api.capture();f.c.modoCalif='letra';finalHtml(f);assert.equal(e.dirty,false);assert.equal(e.revision,0);await f.api.save();assert.equal(e.version,version);assert.equal(f.calls.filter(x=>x.action==='savetransversalaporte').length,0);});
test('Explicit numeric input 15 over a letter A changes mode and versions, unlike view change',async()=>{const f=ui();direct(f.s,'A');await f.api.load();const e=f.api.current(),version=e.version;f.c.modoCalif='num';const inp={value:'15',dataset:{transId:f.s.id,transComp:'tic'}};f.api.bind({querySelectorAll:sel=>sel.includes('.trans-nota')?[inp]:[]});inp.oninput();assert.equal(e.dirty,true);assert.equal(e.evidence.directos[f.s.id].tic.modo,'num');await f.api.save();assert.ok(e.version>version);});
for(const mode of ['letra','num'])test('Transversal Calificar '+mode+' displays only chosen representation and letter source never fabricates number',async()=>{const f=ui();save(f.s,raw(f.s));await f.api.load();f.c.modoCalif=mode;const col=f.api.columns('2026-10-14')[0];let html=f.api.cell(f.s.roster[0],col,'2026-10-14');if(mode==='letra'){assert.match(html,/nivel-b on/);assert.doesNotMatch(html,/12|type="number"/);}else assert.match(html,/value="12"/);const e=f.api.current(),k=f.c.IERegistroEvaluacion.sessionKey(e.evidence.sessions[0]);e.evidence.grades[k][f.s.id]=f.c.IERegistroEvaluacion.valor({modo:'letra',valor:'A'});html=f.api.cell(f.s.roster[0],col,'2026-10-14');if(mode==='num'){assert.match(html,/value=""/);assert.doesNotMatch(html,/value="15"/);}});

function academicUi(){
 const f=ui();Object.assign(f.c,{leerNota:(map,k)=>{const v=map[k];return v&&!v.borrado?v:null},pad2:String,numToLetter:f.c.IERegistroEvaluacion.numToLetter,letterToNum:f.c.IERegistroEvaluacion.letterToNum,promedioNums:f.c.IERegistroEvaluacion.promedioNums,eqClass:()=>'',sincronizarEdicionRegistro:()=>{},fixHdrHeight:()=>{},loadStore:()=>{},capsDeComp:()=>[],colsCalificar:()=>[{comp:'Académica',cap:'Cap',origen:'academica'}],capKeyHoy:()=> 'academic-grade',actualizarContadores:()=>{},finalKey:()=> 'secundaria||I||2||A||Matemática||Académica||student',concAreaKey:()=> 'conclusion',requiereConclusion:()=>false,aulaKey:()=> '2|A',bimestreHabilitado:()=>true});
 ['notaDirectaAlumno','notaDesdeSesiones','notaCompAlumno','renderStudents','renderFinales','renderAvance'].forEach(n=>vm.runInContext(extract(n),f.c));return f;
}
for(const mode of ['letra','num'])test('Academic Calificar '+mode+' hides reference number of original letter and shows actual numeric grade',()=>{
 const f=academicUi();f.c.modoCalif=mode;f.c.store.grades['academic-grade']={nota20:15,nivel:'A',origen:'letra'};f.c.renderStudents();let html=f.el('stuList').innerHTML;
 assert.doesNotMatch(html,/value="15"/);if(mode==='letra'){assert.doesNotMatch(html,/type="number"/);assert.match(html,/nivel-a on/);}else assert.match(html,/value=""/);
 f.c.store.grades['academic-grade']={nota20:16,nivel:'A',origen:'numero'};f.c.renderStudents();html=f.el('stuList').innerHTML;if(mode==='num')assert.match(html,/value="16"/);else assert.doesNotMatch(html,/value="16"|type="number"/);
});
for(const mode of ['letra','num'])test('Academic Promedios '+mode+' respects direct priority and never invents numeric value of original letter',()=>{const f=academicUi();f.c.modoCalif=mode;f.c.store.finales['secundaria||I||2||A||Matemática||Académica||student']={nota20:15,nivel:'A',origen:'letra'};f.c.renderFinales();let html=f.el('finLista').innerHTML;assert.match(html,/nivel-a on|>A<\/span>/);assert.doesNotMatch(html,/value="15"/);if(mode==='letra'){assert.doesNotMatch(html,/type="number"/);assert.doesNotMatch(f.el('finResumen').innerHTML,/0–20/);}else assert.match(html,/value=""/);f.c.store.finales['secundaria||I||2||A||Matemática||Académica||student']={nota20:16,nivel:'A',origen:'numero'};f.c.renderFinales();if(mode==='num')assert.match(f.el('finLista').innerHTML,/value="16"/);assert.equal(f.c.notaCompAlumno('Académica',f.s.id).src,'P');});
for(const mode of ['letra','num'])test('Academic Resumen '+mode+' hides letter-reference number and still displays real numeric direct',()=>{const f=academicUi();f.c.modoCalif=mode;f.c.store.finales['secundaria||I||2||A||Matemática||Académica||student']={nota20:15,nivel:'A',origen:'letra'};f.c.renderAvance();let html=f.el('avanceBox').innerHTML;assert.match(html,/>A<\/span>/);const firstCell=html.match(/<td><div class="fin-cell">([\s\S]*?)<\/td>/)[1];assert.doesNotMatch(firstCell,/>15<\/div>/);f.c.store.finales['secundaria||I||2||A||Matemática||Académica||student']={nota20:16,nivel:'A',origen:'numero'};f.c.renderAvance();html=f.el('avanceBox').innerHTML;if(mode==='num')assert.match(html,/>16<\/div>/);else assert.doesNotMatch(html,/>16<\/div>/);});
test('Academic collectors preserve letter-origin blank fields and exact values when simply saving numeric view',()=>{
 const f=academicUi();const letter={nota20:15,nivel:'A',origen:'letra',ts:100};f.c.store.grades['academic-grade']=clone(letter);f.c.store.finales['secundaria||I||2||A||Matemática||Académica||student']=clone(letter);
 const inp={value:'',readOnly:false,dataset:{nom:'student',comp:'Académica',cap:'Cap'}},cell={dataset:{fin:'student',comp:'Académica'},querySelector:()=>({value:'',readOnly:false})};
 f.c.document.querySelectorAll=sel=>sel==='.cal-nota'?[inp]:sel.includes('#finLista')?[cell]:[];f.c.guardarAsistencia=()=>{};f.c.saveCapsElegidas=()=>{};f.c.guardarMeta=()=>{};vm.runInContext(extract('recolectarPantalla'),f.c);vm.runInContext(extract('guardarFinales'),f.c);f.c.recolectarPantalla();f.c.guardarFinales();assert.deepEqual(clone(f.c.store.grades['academic-grade']),letter);assert.deepEqual(clone(f.c.store.finales['secundaria||I||2||A||Matemática||Académica||student']),letter);
 inp.value='16';cell.querySelector=()=>({value:'16',readOnly:false});f.c.recolectarPantalla();assert.equal(f.c.store.grades['academic-grade'].origen,'numero');assert.equal(f.c.store.grades['academic-grade'].nota20,16);assert.equal(f.c.store.finales['secundaria||I||2||A||Matemática||Académica||student'].origen,'numero');assert.equal(f.c.store.finales['secundaria||I||2||A||Matemática||Académica||student'].nota20,16);
});
test('Actual presentation toggle roundtrip leaves transversal evidence, direct and Tutor/AIP versions intact',async()=>{const f=ui();direct(f.s,'A');await f.api.load();const evidence=JSON.stringify(f.api.current().evidence),version=f.s.load('pip').versionAportes;f.c.localStorage={setItem(){}};f.c.syncModoBtns=()=>{};vm.runInContext(extract('setModoCalif'),f.c);for(const m of ['letra','num','letra'])f.c.setModoCalif(m);assert.equal(JSON.stringify(f.api.current().evidence),evidence);assert.equal(f.api.current().revision,0);assert.equal(f.api.current().dirty,false);assert.equal(f.s.load('pip').versionAportes,version);assert.equal(f.calls.filter(c=>c.action==='savetransversalaporte').length,0);});
